type DailyPlan={date:string;questions:Q[];done:string[]};
type ExamResult={id:string;date:string;score:number;correct:number;total:number;seconds:number;details:{question:Q;answer:number|null;correct:boolean}[]};
type ReviewTask={question:Q;due:string;attempts:number};
function makeDailyPlan(records:Rec[]):DailyPlan{const date=new Date().toLocaleDateString('zh-CN');const performance=skills.map(s=>{const xs=records.filter(r=>r.question.skill===s.id);return {id:s.id,count:xs.length,rate:xs.length?xs.filter(r=>r.correct).length/xs.length:1,avg:xs.length?xs.reduce((n,r)=>n+r.seconds,0)/xs.length:0}}).filter(s=>s.count>0).sort((a,b)=>a.rate-b.rate||b.avg-a.avg);const weak=performance[0]?.id||'base';const weakQs=Array.from({length:4},()=>generateQuestion(weak));const mixedQs=Array.from({length:4},()=>generateQuestion('all'));const dayIndex=new Date().getDate()%materialSets.length;const materialQs=materialSets[dayIndex].questions.map(q=>({...q,id:'daily-'+date+'-'+q.id}));const questions=[...weakQs,...mixedQs,...materialQs.slice(0,4)].map((q,i)=>({...q,id:'daily-'+date+'-'+i+'-'+q.id}));return {date,questions,done:[]};}
